/**
 * RA Л5: `content/legal/{privacy,terms}.{kk,ru}.md` → `src/app/(app)/(legal)/legal.generated.ts` (HTML strings).
 * The generated file is committed (like `assets.generated.ts`); `check:messages` runs `--check`, so CI fails if it is
 * stale. Also warns (does not fail) about `[ЮРИСТ` notes left in the texts — blocking production on them is the
 * founder's decision (CONTENT_REVIEW §8).
 *   pnpm tsx scripts/build-legal.ts [--check [--strict]]   (--strict: fail on [ЮРИСТ notes — deploy-prod.yml)
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { lawyerNotes, markdownToHtml } from "./lib/legal-markdown";

const ROOT = resolve(import.meta.dirname, "..");
const OUT = resolve(ROOT, "src/app/(app)/(legal)/legal.generated.ts");
const PAGES = ["privacy", "terms"] as const;
const LOCALES = ["kk", "ru"] as const;

const data: Record<string, Record<string, { title: string; html: string }>> = {};
let notes = 0;
for (const page of PAGES) {
  data[page] = {};
  for (const locale of LOCALES) {
    const md = readFileSync(resolve(ROOT, `content/legal/${page}.${locale}.md`), "utf8");
    const n = lawyerNotes(md);
    if (n)
      console.warn(
        `build-legal: WARNING ${page}.${locale}.md — ${n} × [ЮРИСТ …] (draft; must be gone before the final text)`,
      );
    notes += n;
    const title = md.match(/^#\s+(.+)$/m)?.[1]?.trim() ?? page;
    data[page]![locale] = { title, html: markdownToHtml(md) };
  }
}

const source =
  `// Generated by scripts/build-legal.ts from content/legal/*.md — do not edit by hand.\n` +
  `export const LEGAL = ${JSON.stringify(data, null, 2)} as const;\n`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8");
  } catch {}
  if (current !== source) {
    console.error("check:legal: src/app/(app)/(legal)/legal.generated.ts is stale — run pnpm tsx scripts/build-legal.ts");
    process.exit(1);
  }
  if (notes && process.argv.includes("--strict")) {
    // RA review П3: production deploy fails while lawyer notes remain (local / preview only warn).
    console.error(`check:legal --strict: ${notes} × [ЮРИСТ …] left in content/legal — not for production users`);
    process.exit(1);
  }
  console.log(
    `check:legal: OK — ${PAGES.length * LOCALES.length} pages${notes ? `; WARNING ${notes} × [ЮРИСТ …] left (drafts)` : ""}`,
  );
} else {
  writeFileSync(OUT, source);
  console.log(`build-legal: ${OUT.replace(ROOT, ".")} written`);
}
